const dicts = { ar, en };
let lang = 'ar';

export function t(key, params, fallback) {
  let s = dicts[lang][key] ?? dicts.en[key] ?? fallback ?? key;
  if (params) for (const [k, v] of Object.entries(params)) s = s.split('{' + k + '}').join(String(v));
  return s;
}

export function setLang(l) {
  lang = dicts[l] ? l : 'ar';
  const html = document.documentElement;
  html.lang = lang; html.dir = lang === 'ar' ? 'rtl' : 'ltr';
  const badge = document.getElementById('lang-badge'); if (badge) badge.textContent = lang === 'ar' ? 'EN' : 'ع';
  bus.emit('lang', lang);
}
export const getLang = () => lang;

export function applyI18n(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-title]').forEach((el) => { el.title = t(el.dataset.i18nTitle); el.setAttribute('aria-label', t(el.dataset.i18nTitle)); });
  root.querySelectorAll('[data-i18n-placeholder]').forEach((el) => { el.placeholder = t(el.dataset.i18nPlaceholder); });
  document.title = t('app.name') + ' — ' + t('app.tagline');
}

export const dictionaries = dicts;
